import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {readFileSync,writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
const at=f=>fileURLToPath(new URL(f,import.meta.url));
const fn='_M0FP210JingLan0v03stn19append__order__rule';
const block=/  const before_suffix = [^\n]+\n  const after_suffix = [^\n]+\n  const id = [^\n]+/;
for(const driver of ['lookupbench','deepbench']){
 const js=readFileSync(at('base-'+driver+'.js'),'utf8').replaceAll('\r\n','\n');
 const start=js.indexOf('function '+fn+'('), end=js.indexOf('\nfunction ',start+1);
 assert(start>=0&&end>start);
 const region=js.slice(start,end);
 const old=region.match(block)?.[0];
 assert(old?.includes('to__string')&&old.includes('order'));
 const index=old.indexOf('  const id =');
 for(const mode of ['count','both','concat','control']){
  const head='const profile={branches:0,conversions:0,concatenations:0,distinctLabels:0,ms:0};\n'+
    'const seen=new WeakMap();\n'+
    "process.once('exit',()=>console.error(JSON.stringify(profile)));\n";
  const timer='  const phaseStart=performance.now();\n';
  const stop='  profile.ms+=performance.now()-phaseStart;';
  const instrumented=mode==='count'?old+
    '\n  profile.branches++;profile.conversions+=2;profile.concatenations++;\n'+
    '  let labels=seen.get(rule_ids);\n  if(!labels){labels=new Set();seen.set(rule_ids,labels)}\n'+
    '  if(!labels.has(id)){labels.add(id);profile.distinctLabels++}':
    mode==='both'?timer+old+'\n'+stop:
    mode==='concat'?old.slice(0,index)+timer+old.slice(index)+'\n'+stop:
    timer+stop+'\n'+old;
  writeFileSync(at('base-'+driver+'-'+mode+'.js'),head+js.slice(0,start)+region.replace(old,instrumented)+js.slice(end));
 }
}
const results=[];
for(const name of ['maintenance','first-pair','four-resources','max-model','tight-impossible']){
 const deep=name==='tight-impossible';
 const run=mode=>{
  const args=[at('base-'+(deep?'deepbench':'lookupbench')+'-'+mode+'.js'),...(deep?[]:[name])];
  const r=spawnSync(process.execPath,args,{encoding:'utf8',timeout:45000});
  assert.ifError(r.error);
  assert.equal(r.status,0,r.stderr);
  assert.equal(r.stdout.trim().split(/\r?\n/).length,9);
  return JSON.parse(r.stderr);
 };
 const {ms,...counts}=run('count');
 assert.equal(counts.branches,counts.concatenations);
 assert.equal(counts.conversions,2*counts.branches);
 const phase={both:[],concat:[],control:[]};
 for(let i=0;i<3;i++)for(const mode of i%2?Object.keys(phase).reverse():Object.keys(phase))phase[mode].push(run(mode).ms);
 results.push({name,counts,phase});
 console.log(name,JSON.stringify(counts),JSON.stringify(phase));
}
writeFileSync(at('baseline-probe.json'),JSON.stringify(results,null,2)+'\n');

